/* Fast dominant eigenpair for small real matrices (n <= MAXN).
 *
 * Pure C: no BLAS/LAPACK, no numpy C-API.  The only interface used is the
 * Python buffer protocol, so this stays valid across numpy/scipy versions.
 *
 *   1. Householder reduction to upper Hessenberg form (real arithmetic).
 *   2. Complex single-shift (Wilkinson shift) QR iteration with deflation.
 *   3. Dominant eigenvalue = largest magnitude.
 *   4. Eigenvector by inverse iteration on (A - lambda I) via one complex LU
 *      with partial pivoting.
 *   5. Residual check; on any failure return None -> caller falls back to
 *      numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <complex.h>
#include <math.h>
#include <string.h>

#define MAXN 32
#define DEPS 2.2204460492503131e-16

typedef double _Complex cplx;

static void eig2(cplx a, cplx b, cplx c, cplx d, cplx *l1, cplx *l2)
{
    cplx tr = a + d;
    cplx det = a * d - b * c;
    cplx disc = csqrt(tr * tr - 4.0 * det);
    cplx p = 0.5 * (tr + disc);
    cplx m = 0.5 * (tr - disc);
    if (cabs(m) > cabs(p)) {
        cplx t = p; p = m; m = t;
    }
    if (cabs(p) > 0.0)
        m = det / p;
    *l1 = p;
    *l2 = m;
}

static int compute_eigvals(const double *A, int n, cplx *w)
{
    double H[MAXN * MAXN];
    double v[MAXN];
    cplx C[MAXN * MAXN];
    cplx cs[MAXN], sn[MAXN];
    int i, j, k, hi, l, iter, total;

    memcpy(H, A, sizeof(double) * (size_t)(n * n));

    /* ---- Hessenberg reduction ---- */
    for (k = 0; k + 2 < n; ++k) {
        int m = n - k - 1;
        double nrm = 0.0, vtv = 0.0, alpha, beta, s;
        for (i = 0; i < m; ++i) {
            v[i] = H[(k + 1 + i) * n + k];
            nrm += v[i] * v[i];
        }
        nrm = sqrt(nrm);
        if (nrm == 0.0)
            continue;
        alpha = (v[0] >= 0.0) ? -nrm : nrm;
        v[0] -= alpha;
        for (i = 0; i < m; ++i)
            vtv += v[i] * v[i];
        if (vtv == 0.0)
            continue;
        beta = 2.0 / vtv;
        for (j = k; j < n; ++j) {
            s = 0.0;
            for (i = 0; i < m; ++i)
                s += v[i] * H[(k + 1 + i) * n + j];
            s *= beta;
            for (i = 0; i < m; ++i)
                H[(k + 1 + i) * n + j] -= s * v[i];
        }
        for (i = 0; i < n; ++i) {
            s = 0.0;
            for (j = 0; j < m; ++j)
                s += H[i * n + k + 1 + j] * v[j];
            s *= beta;
            for (j = 0; j < m; ++j)
                H[i * n + k + 1 + j] -= s * v[j];
        }
        for (i = k + 2; i < n; ++i)
            H[i * n + k] = 0.0;
    }

    for (i = 0; i < n * n; ++i)
        C[i] = (cplx)H[i];

    /* ---- complex shifted QR, eigenvalues only ---- */
    hi = n - 1;
    iter = 0;
    total = 0;
    while (hi >= 0) {
        cplx shift, l1, l2;
        if (hi == 0) {
            w[0] = C[0];
            break;
        }
        l = 0;
        for (i = hi; i >= 1; --i) {
            double s = cabs(C[(i - 1) * n + i - 1]) + cabs(C[i * n + i]);
            if (s == 0.0)
                s = 1.0;
            if (cabs(C[i * n + i - 1]) <= DEPS * s) {
                C[i * n + i - 1] = 0.0;
                l = i;
                break;
            }
        }
        if (l == hi) {
            w[hi] = C[hi * n + hi];
            hi -= 1;
            iter = 0;
            continue;
        }
        if (l == hi - 1) {
            eig2(C[(hi - 1) * n + hi - 1], C[(hi - 1) * n + hi],
                 C[hi * n + hi - 1], C[hi * n + hi], &l1, &l2);
            w[hi - 1] = l1;
            w[hi] = l2;
            hi -= 2;
            iter = 0;
            continue;
        }
        iter += 1;
        total += 1;
        if (iter > 50 || total > 40 * n + 200)
            return -1;
        if (iter % 12 == 0) {
            shift = C[hi * n + hi] + cabs(C[hi * n + hi - 1])
                    + cabs(C[(hi - 1) * n + hi - 2]);
        } else {
            cplx d = C[hi * n + hi];
            eig2(C[(hi - 1) * n + hi - 1], C[(hi - 1) * n + hi],
                 C[hi * n + hi - 1], d, &l1, &l2);
            shift = (cabs(l1 - d) <= cabs(l2 - d)) ? l1 : l2;
        }
        for (i = l; i <= hi; ++i)
            C[i * n + i] -= shift;
        for (i = l; i < hi; ++i) {
            cplx a = C[i * n + i], b = C[(i + 1) * n + i], cc, ss;
            double r = hypot(cabs(a), cabs(b));
            if (r == 0.0) {
                cc = 1.0;
                ss = 0.0;
            } else {
                cc = conj(a) / r;
                ss = conj(b) / r;
            }
            cs[i] = cc;
            sn[i] = ss;
            for (j = i; j <= hi; ++j) {
                cplx x = C[i * n + j], y = C[(i + 1) * n + j];
                C[i * n + j] = cc * x + ss * y;
                C[(i + 1) * n + j] = conj(cc) * y - conj(ss) * x;
            }
        }
        for (i = l; i < hi; ++i) {
            cplx cc = cs[i], ss = sn[i];
            int top = (i + 2 <= hi) ? (i + 2) : hi;
            for (k = l; k <= top; ++k) {
                cplx x = C[k * n + i], y = C[k * n + i + 1];
                C[k * n + i] = conj(cc) * x + conj(ss) * y;
                C[k * n + i + 1] = cc * y - ss * x;
            }
        }
        for (i = l; i <= hi; ++i)
            C[i * n + i] += shift;
    }
    return 0;
}

static int dominant_pair(const double *A, int n, cplx *lam_out, cplx *x)
{
    cplx w[MAXN];
    cplx M[MAXN * MAXN];
    cplx b[MAXN];
    int piv[MAXN];
    int i, j, k, it, best;
    double anorm = 0.0, tiny, best_mag, nx;
    cplx lam;

    for (i = 0; i < n * n; ++i) {
        double a = A[i];
        if (!isfinite(a))
            return -1;
        anorm += a * a;
    }
    anorm = sqrt(anorm);

    if (n == 1) {
        *lam_out = (cplx)A[0];
        x[0] = 1.0;
        return 0;
    }

    if (compute_eigvals(A, n, w) != 0)
        return -1;

    best = 0;
    best_mag = -1.0;
    for (i = 0; i < n; ++i) {
        double m;
        if (!isfinite(creal(w[i])) || !isfinite(cimag(w[i])))
            return -1;
        m = cabs(w[i]);
        if (m > best_mag) {
            best_mag = m;
            best = i;
        }
    }
    lam = w[best];

    /* ---- inverse iteration on (A - lam I) ---- */
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            M[i * n + j] = (cplx)A[i * n + j] - ((i == j) ? lam : 0.0);

    tiny = DEPS * (anorm > 0.0 ? anorm : 1.0);
    for (k = 0; k < n; ++k) {
        int p = k;
        double pm = cabs(M[k * n + k]);
        for (i = k + 1; i < n; ++i) {
            double m = cabs(M[i * n + k]);
            if (m > pm) {
                pm = m;
                p = i;
            }
        }
        piv[k] = p;
        if (p != k)
            for (j = 0; j < n; ++j) {
                cplx t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        if (cabs(M[k * n + k]) < tiny)
            M[k * n + k] = tiny;
        for (i = k + 1; i < n; ++i) {
            cplx f = M[i * n + k] / M[k * n + k];
            M[i * n + k] = f;
            if (f == 0.0)
                continue;
            for (j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
        }
    }

    for (i = 0; i < n; ++i)
        x[i] = 1.0 + 0.05 * (double)i;

    for (it = 0; it < 2; ++it) {
        for (i = 0; i < n; ++i)
            b[i] = x[i];
        for (k = 0; k < n; ++k)
            if (piv[k] != k) {
                cplx t = b[k];
                b[k] = b[piv[k]];
                b[piv[k]] = t;
            }
        for (i = 1; i < n; ++i) {
            cplx s = b[i];
            for (j = 0; j < i; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s;
        }
        for (i = n - 1; i >= 0; --i) {
            cplx s = b[i];
            for (j = i + 1; j < n; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s / M[i * n + i];
        }
        nx = 0.0;
        for (i = 0; i < n; ++i) {
            double re = creal(b[i]), im = cimag(b[i]);
            if (!isfinite(re) || !isfinite(im))
                return -1;
            nx += re * re + im * im;
        }
        nx = sqrt(nx);
        if (!(nx > 0.0) || !isfinite(nx))
            return -1;
        for (i = 0; i < n; ++i)
            x[i] = b[i] / nx;
    }

    /* ---- residual check ---- */
    {
        double res = 0.0, tol;
        for (i = 0; i < n; ++i) {
            cplx s = -lam * x[i];
            for (j = 0; j < n; ++j)
                s += (cplx)A[i * n + j] * x[j];
            res += creal(s) * creal(s) + cimag(s) * cimag(s);
        }
        res = sqrt(res);
        tol = 1.0e-9 + 1.0e-8 * (anorm > best_mag ? anorm : best_mag);
        if (!(res <= tol))
            return -1;
    }

    *lam_out = lam;
    return 0;
}

static PyObject *py_dominant(PyObject *self, PyObject *arg)
{
    Py_buffer view;
    cplx lam, x[MAXN];
    int n, rc;
    PyObject *ba, *cval, *tup;

    if (PyObject_GetBuffer(arg, &view, PyBUF_FORMAT | PyBUF_ND) != 0) {
        PyErr_Clear();
        Py_RETURN_NONE;
    }
    if (view.ndim != 2 || view.itemsize != (Py_ssize_t)sizeof(double)
        || view.format == NULL || strcmp(view.format, "d") != 0
        || view.shape[0] != view.shape[1] || view.shape[0] < 1
        || view.shape[0] > MAXN || !PyBuffer_IsContiguous(&view, 'C')
        || view.buf == NULL) {
        PyBuffer_Release(&view);
        Py_RETURN_NONE;
    }
    n = (int)view.shape[0];
    rc = dominant_pair((const double *)view.buf, n, &lam, x);
    PyBuffer_Release(&view);
    if (rc != 0)
        Py_RETURN_NONE;

    ba = PyByteArray_FromStringAndSize((const char *)x,
                                       (Py_ssize_t)(2 * n * sizeof(double)));
    if (ba == NULL)
        return NULL;
    cval = PyComplex_FromDoubles(creal(lam), cimag(lam));
    if (cval == NULL) {
        Py_DECREF(ba);
        return NULL;
    }
    tup = PyTuple_New(2);
    if (tup == NULL) {
        Py_DECREF(ba);
        Py_DECREF(cval);
        return NULL;
    }
    PyTuple_SET_ITEM(tup, 0, cval);
    PyTuple_SET_ITEM(tup, 1, ba);
    return tup;
}

static PyMethodDef methods[] = {
    {"dominant", py_dominant, METH_O,
     "dominant(A) -> (complex eigenvalue, bytearray eigenvector) or None"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigfast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigfast(void)
{
    return PyModule_Create(&moduledef);
}
