                C[i * n + j] = cc * x + ss * y;
                C[(i + 1) * n + j] = conj(cc) * y - conj(ss) * x;
            }
        }
        for (i = l; i < hi; ++i) {
            cplx cc = cs[i], ss = sn[i];
            int top = (i + 2 <= hi) ? (i + 2) : hi;
            for (k = l; k <= top; ++k) {
                cplx x = C[k * n + i], y = C[k * n + i + 1];
                C[k * n + i] = conj(cc) * x + conj(ss) * y;
                C[k * n + i + 1] = cc * y - ss * x;
            }
        }
        for (i = l; i <= hi; ++i)
            C[i * n + i] += shift;
    }
    return 0;
}

static int dominant_pair(const double *A, int n, cplx *lam_out, cplx *x)
{
    cplx w[MAXN];
    cplx M[MAXN * MAXN];
    cplx b[MAXN];
    int piv[MAXN];
    int i, j, k, it, best;
    double anorm = 0.0, tiny, best_mag, nx;
    cplx lam;

    for (i = 0; i < n * n; ++i) {
        double a = A[i];
        if (!isfinite(a))
            return -1;
        anorm += a * a;
    }
    anorm = sqrt(anorm);

    if (n == 1) {
        *lam_out = (cplx)A[0];
        x[0] = 1.0;
        return 0;
    }

    if (compute_eigvals(A, n, w) != 0)
        return -1;

    best = 0;
    best_mag = -1.0;
    for (i = 0; i < n; ++i) {
        double m;
        if (!isfinite(creal(w[i])) || !isfinite(cimag(w[i])))
            return -1;
        m = cabs(w[i]);
        if (m > best_mag) {
            best_mag = m;
            best = i;
        }
    }
    lam = w[best];

    /* ---- inverse iteration on (A - lam I) ---- */
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            M[i * n + j] = (cplx)A[i * n + j] - ((i == j) ? lam : 0.0);

    tiny = DEPS * (anorm > 0.0 ? anorm : 1.0);
    for (k = 0; k < n; ++k) {
        int p = k;
        double pm = cabs(M[k * n + k]);
        for (i = k + 1; i < n; ++i) {
            double m = cabs(M[i * n + k]);
            if (m > pm) {
                pm = m;
                p = i;
            }
        }
        piv[k] = p;
        if (p != k)
            for (j = 0; j < n; ++j) {
                cplx t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        if (cabs(M[k * n + k]) < tiny)
            M[k * n + k] = tiny;
        for (i = k + 1; i < n; ++i) {
            cplx f = M[i * n + k] / M[k * n + k];
            M[i * n + k] = f;
            if (f == 0.0)
                continue;
            for (j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
        }
    }

    for (i = 0; i < n; ++i)
        x[i] = 1.0 + 0.05 * (double)i;

    for (it = 0; it < 2; ++it) {
        for (i = 0; i < n; ++i)
            b[i] = x[i];
        for (k = 0; k < n; ++k)
            if (piv[k] != k) {
                cplx t = b[k];
                b[k] = b[piv[k]];
                b[piv[k]] = t;
            }
        for (i = 1; i < n; ++i) {
            cplx s = b[i];
            for (j = 0; j < i; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s;
        }
        for (i = n - 1; i >= 0; --i) {
            cplx s = b[i];
            for (j = i + 1; j < n; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s / M[i * n + i];
        }
        nx = 0.0;
        for (i = 0; i < n; ++i) {
            double re = creal(b[i]), im = cimag(b[i]);
            if (!isfinite(re) || !isfinite(im))
                return -1;
            nx += re * re + im * im;
        }
        nx = sqrt(nx);
        if (!(nx > 0.0) || !isfinite(nx))
            return -1;
        for (i = 0; i < n; ++i)
            x[i] = b[i] / nx;
    }

    /* ---- residual check ---- */
    {
        double res = 0.0, tol;
        for (i = 0; i < n; ++i) {
            cplx s = -lam * x[i];
            for (j = 0; j < n; ++j)
                s += (cplx)A[i * n + j] * x[j];
            res += creal(s) * creal(s) + cimag(s) * cimag(s);
        }
        res = sqrt(res);
        tol = 1.0e-9 + 1.0e-8 * (anorm > best_mag ? anorm : best_mag);
        if (!(res <= tol))
            return -1;
    }

    *lam_out = lam;
    return 0;
}

static PyObject *py_dominant(PyObject *self, PyObject *arg)
{
    Py_buffer view;
    cplx lam, x[MAXN];
    int n, rc;
    PyObject *ba, *cval, *tup;

    if (PyObject_GetBuffer(arg, &view, PyBUF_FORMAT | PyBUF_ND) != 0) {
        PyErr_Clear();
        Py_RETURN_NONE;
    }
    if (view.ndim != 2 || view.itemsize != (Py_ssize_t)sizeof(double)
        || view.format == NULL || strcmp(view.format, "d") != 0
        || view.shape[0] != view.shape[1] || view.shape[0] < 1
        || view.shape[0] > MAXN || !PyBuffer_IsContiguous(&view, 'C')
        || view.buf == NULL) {
        PyBuffer_Release(&view);
        Py_RETURN_NONE;
    }
    n = (int)view.shape[0];
    rc = dominant_pair((const double *)view.buf, n, &lam, x);
    PyBuffer_Release(&view);
    if (rc != 0)
        Py_RETURN_NONE;

    ba = PyByteArray_FromStringAndSize((const char *)x,
                                       (Py_ssize_t)(2 * n * sizeof(double)));
    if (ba == NULL)
        return NULL;
    cval = PyComplex_FromDoubles(creal(lam), cimag(lam));
    if (cval == NULL) {
        Py_DECREF(ba);
        return NULL;
    }
    tup = PyTuple_New(2);
    if (tup == NULL) {
        Py_DECREF(ba);
        Py_DECREF(cval);
        return NULL;
    }
    PyTuple_SET_ITEM(tup, 0, cval);
    PyTuple_SET_ITEM(tup, 1, ba);
    return tup;
}

static PyMethodDef methods[] = {
    {"dominant", py_dominant, METH_O,
     "dominant(A) -> (complex eigenvalue, bytearray eigenvector) or None"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigfast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigfast(void)
{
    return PyModule_Create(&moduledef);
}
