/* Fast dominant eigenpair for small real matrices (n <= MAXN).
 *
 * Pure C: no BLAS/LAPACK, no numpy C-API.  The only interface used is the
 * Python buffer protocol, so this stays valid across numpy/scipy versions.
 *
 *   1. Householder reduction to upper Hessenberg form.
 *   2. Francis double-shift QR iteration with deflation (real arithmetic,
 *      eigenvalues only) -> all eigenvalues.
 *   3. Dominant eigenvalue = largest magnitude.
 *   4. Eigenvector by inverse iteration on (A - lambda I) using one complex LU
 *      with partial pivoting.
 *   5. Residual check; on any failure return None -> caller falls back to
 *      numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <complex.h>
#include <math.h>
#include <string.h>

#define MAXN 20
#define DEPS 2.2204460492503131e-16
#define SIGN(a, b) ((b) >= 0.0 ? fabs(a) : -fabs(a))

typedef double _Complex cplx;

/* |z| without the (slow, libcall) hypot/cabs; overflow is irrelevant here. */
static inline double amag(cplx z)
{
    double re = creal(z), im = cimag(z);
    return sqrt(re * re + im * im);
}

/* ---- Householder reduction to upper Hessenberg form (in place) ---- */
static void hessenberg(double *H, int n)
{
    double v[MAXN];
    int i, j, k;

    for (k = 0; k + 2 < n; ++k) {
        int m = n - k - 1;
        double nrm = 0.0, vtv = 0.0, alpha, beta, s;
        for (i = 0; i < m; ++i) {
            v[i] = H[(k + 1 + i) * n + k];
            nrm += v[i] * v[i];
        }
        nrm = sqrt(nrm);
        if (nrm == 0.0)
            continue;
        alpha = (v[0] >= 0.0) ? -nrm : nrm;
        v[0] -= alpha;
        for (i = 0; i < m; ++i)
            vtv += v[i] * v[i];
        if (vtv == 0.0)
            continue;
        beta = 2.0 / vtv;
        for (j = k; j < n; ++j) {
            s = 0.0;
            for (i = 0; i < m; ++i)
                s += v[i] * H[(k + 1 + i) * n + j];
            s *= beta;
            for (i = 0; i < m; ++i)
                H[(k + 1 + i) * n + j] -= s * v[i];
        }
        for (i = 0; i < n; ++i) {
            s = 0.0;
            for (j = 0; j < m; ++j)
                s += H[i * n + k + 1 + j] * v[j];
            s *= beta;
            for (j = 0; j < m; ++j)
                H[i * n + k + 1 + j] -= s * v[j];
        }
        for (i = k + 2; i < n; ++i)
            H[i * n + k] = 0.0;
    }
}

/* ---- Francis double-shift QR on an upper Hessenberg matrix ----
 * Eigenvalues only (no Schur vectors).  Returns 0 on success, -1 if some
 * eigenvalue failed to converge.
 */
static int hqr(double *h, int n, double *wr, double *wi)
{
    int i, j, k, l, m = 0, en, its, mmin;
    double anorm = 0.0, p = 0.0, q = 0.0, r = 0.0, s, t, u, v, w, x, y, z;

    for (i = 0; i < n; ++i)
        for (j = (i > 0 ? i - 1 : 0); j < n; ++j)
            anorm += fabs(h[i * n + j]);
    if (anorm == 0.0)
        anorm = 1.0;

    en = n - 1;
    t = 0.0;
    while (en >= 0) {
        its = 0;
        do {
            for (l = en; l >= 1; --l) {
                s = fabs(h[(l - 1) * n + l - 1]) + fabs(h[l * n + l]);
                if (s == 0.0)
                    s = anorm;
                if (fabs(h[l * n + l - 1]) <= DEPS * s) {
                    h[l * n + l - 1] = 0.0;
                    break;
                }
            }
            if (l < 1)
                l = 0;
            x = h[en * n + en];
            if (l == en) {                      /* one root found */
                wr[en] = x + t;
                wi[en] = 0.0;
                en -= 1;
            } else {
                y = h[(en - 1) * n + en - 1];
                w = h[en * n + en - 1] * h[(en - 1) * n + en];
                if (l == en - 1) {              /* two roots found */
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x += t;
                    if (q >= 0.0) {             /* real pair */
                        z = p + SIGN(z, p);
                        wr[en - 1] = wr[en] = x + z;
                        if (z != 0.0)
                            wr[en] = x - w / z;
                        wi[en - 1] = wi[en] = 0.0;
                    } else {                    /* complex pair */
                        wr[en - 1] = wr[en] = x + p;
                        wi[en] = z;
                        wi[en - 1] = -z;
                    }
                    en -= 2;
                } else {                        /* no roots: QR step */
                    if (its == 30)
                        return -1;
                    if (its == 10 || its == 20) {   /* exceptional shift */
                        t += x;
                        for (i = 0; i <= en; ++i)
                            h[i * n + i] -= x;
                        s = fabs(h[en * n + en - 1])
                            + fabs(h[(en - 1) * n + en - 2]);
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    /* form shift and look for two consecutive small
                     * subdiagonal elements */
                    for (m = en - 2; m >= l; --m) {
                        z = h[m * n + m];
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / h[(m + 1) * n + m] + h[m * n + m + 1];
                        q = h[(m + 1) * n + m + 1] - z - r - s;
                        r = h[(m + 2) * n + m + 1];
                        s = fabs(p) + fabs(q) + fabs(r);
                        if (s == 0.0)
                            break;
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l)
                            break;
                        u = fabs(h[m * n + m - 1]) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(h[(m - 1) * n + m - 1]) + fabs(z)
                                       + fabs(h[(m + 1) * n + m + 1]));
                        if (u <= DEPS * v)
                            break;
                    }
                    if (m < l)
                        m = l;
                    for (i = m + 2; i <= en; ++i) {
                        h[i * n + i - 2] = 0.0;
                        if (i != m + 2)
                            h[i * n + i - 3] = 0.0;
                    }
                    /* double QR step on rows l..en, columns m..en */
                    for (k = m; k <= en - 1; ++k) {
                        if (k != m) {
                            p = h[k * n + k - 1];
                            q = h[(k + 1) * n + k - 1];
                            r = 0.0;
                            if (k != en - 1)
                                r = h[(k + 2) * n + k - 1];
                            x = fabs(p) + fabs(q) + fabs(r);
                            if (x != 0.0) {
                                p /= x;
                                q /= x;
                                r /= x;
                            }
                        }
                        s = SIGN(sqrt(p * p + q * q + r * r), p);
                        if (s == 0.0)
                            continue;
                        if (k == m) {
                            if (l != m)
                                h[k * n + k - 1] = -h[k * n + k - 1];
                        } else {
                            h[k * n + k - 1] = -s * x;
                        }
                        p += s;
                        x = p / s;
                        y = q / s;
                        z = r / s;
                        q /= p;
                        r /= p;
                        for (j = k; j <= en; ++j) {  /* row modification */
                            p = h[k * n + j] + q * h[(k + 1) * n + j];
                            if (k != en - 1) {
                                p += r * h[(k + 2) * n + j];
                                h[(k + 2) * n + j] -= p * z;
                            }
                            h[(k + 1) * n + j] -= p * y;
                            h[k * n + j] -= p * x;
                        }
                        mmin = en < k + 3 ? en : k + 3;
                        for (i = l; i <= mmin; ++i) { /* column modification */
                            p = x * h[i * n + k] + y * h[i * n + k + 1];
                            if (k != en - 1) {
                                p += z * h[i * n + k + 2];
                                h[i * n + k + 2] -= p * r;
                            }
                            h[i * n + k + 1] -= p * q;
                            h[i * n + k] -= p;
                        }
                    }
                }
            }
        } while (l < en - 1);
    }
    return 0;
}

static int dominant_pair(const double *A, int n, cplx *lam_out, cplx *x)
{
    double H[MAXN * MAXN];
    double wr[MAXN], wi[MAXN];
    cplx M[MAXN * MAXN];
    cplx b[MAXN];
    int piv[MAXN];
    int i, j, k, it, best;
    double anorm = 0.0, trace = 0.0, tiny, best_mag, nx;
    cplx lam;

    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            double a = A[i * n + j];
            if (!isfinite(a))
                return -1;
            anorm += a * a;
        }
        trace += A[i * n + i];
    }
    anorm = sqrt(anorm);

    if (n == 1) {
        *lam_out = (cplx)A[0];
        x[0] = 1.0;
        return 0;
    }

    memcpy(H, A, sizeof(double) * (size_t)(n * n));
    hessenberg(H, n);
    if (hqr(H, n, wr, wi) != 0)
        return -1;

    best = 0;
    best_mag = -1.0;
    nx = 0.0;
    for (i = 0; i < n; ++i) {
        double m;
        if (!isfinite(wr[i]) || !isfinite(wi[i]))
            return -1;
        m = sqrt(wr[i] * wr[i] + wi[i] * wi[i]);
        nx += wr[i];
        if (m > best_mag) {
            best_mag = m;
            best = i;
        }
    }
    /* cheap global sanity check: sum of eigenvalues == trace */
    if (!(fabs(nx - trace) <= 1e-8 * (anorm > 1.0 ? anorm : 1.0)))
        return -1;
    lam = wr[best] + wi[best] * _Complex_I;

    /* ---- inverse iteration on (A - lam I) ---- */
    for (i = 0; i < n; ++i)
        for (j = 0; j < n; ++j)
            M[i * n + j] = (cplx)A[i * n + j] - ((i == j) ? lam : 0.0);

    tiny = DEPS * (anorm > 0.0 ? anorm : 1.0);
    for (k = 0; k < n; ++k) {
        int p = k;
        double pm = amag(M[k * n + k]);
        for (i = k + 1; i < n; ++i) {
            double m = amag(M[i * n + k]);
            if (m > pm) {
                pm = m;
                p = i;
            }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; ++j) {
                cplx tmp = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = tmp;
            }
        }
        if (amag(M[k * n + k]) < tiny)
            M[k * n + k] = tiny;
        for (i = k + 1; i < n; ++i) {
            cplx f = M[i * n + k] / M[k * n + k];
            M[i * n + k] = f;
            if (f == 0.0)
                continue;
            for (j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
        }
    }

    for (i = 0; i < n; ++i)
        x[i] = 1.0 + 0.05 * (double)i;

    for (it = 0; it < 2; ++it) {
        for (i = 0; i < n; ++i)
            b[i] = x[i];
        for (k = 0; k < n; ++k) {
            if (piv[k] != k) {
                cplx tmp = b[k];
                b[k] = b[piv[k]];
                b[piv[k]] = tmp;
            }
        }
        for (i = 1; i < n; ++i) {
            cplx s = b[i];
            for (j = 0; j < i; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s;
        }
        for (i = n - 1; i >= 0; --i) {
            cplx s = b[i];
            for (j = i + 1; j < n; ++j)
                s -= M[i * n + j] * b[j];
            b[i] = s / M[i * n + i];
        }
        nx = 0.0;
        for (i = 0; i < n; ++i) {
            double re = creal(b[i]), im = cimag(b[i]);
            if (!isfinite(re) || !isfinite(im))
                return -1;
            nx += re * re + im * im;
        }
        nx = sqrt(nx);
        if (!(nx > 0.0) || !isfinite(nx))
            return -1;
        for (i = 0; i < n; ++i)
            x[i] = b[i] / nx;
    }

    /* ---- residual check (guards against any breakdown above) ---- */
    {
        double res = 0.0, tol;
        for (i = 0; i < n; ++i) {
            cplx s = -lam * x[i];
